:root {
  color-scheme: dark;
  --bg: #121212;
  --bg-soft: #1e1e1e;
  --fg: #f5f5f5;
  --fg-dim: #9b9b9b;
  --accent: #1db954;
  --border: #2a2a2a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}

.panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-soft);
}

.cover {
  width: 36px;
  height: 36px;
  border-radius: 4px;
  object-fit: cover;
  background: #333;
  flex-shrink: 0;
}

.track-meta {
  min-width: 0;
  flex: 1;
}

.track-name {
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.track-artist {
  font-size: 11px;
  color: var(--fg-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.icon-btn {
  background: none;
  border: none;
  color: var(--fg-dim);
  cursor: pointer;
  padding: 6px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.icon-btn:hover { background: rgba(255,255,255,0.08); color: var(--fg); }

.lyrics-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 16px 20px;
  scroll-behavior: smooth;
}

.lyrics-line {
  font-size: 15px;
  line-height: 1.6;
  color: var(--fg-dim);
  padding: 3px 0;
  transition: color 0.2s ease, transform 0.2s ease;
  transform-origin: left center;
}

.lyrics-line.active {
  color: var(--fg);
  font-weight: 700;
  transform: scale(1.03);
}

.status-msg {
  color: var(--fg-dim);
  font-size: 13px;
  padding: 20px;
  text-align: center;
}

.attribution {
  padding: 6px 14px;
  font-size: 10px;
  color: #666;
  border-top: 1px solid var(--border);
  background: var(--bg-soft);
  display: flex;
  justify-content: space-between;
}
.attribution a { color: #6ee08a; text-decoration: none; }

.setup {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.setup label {
  font-size: 12px;
  color: var(--fg-dim);
}

.setup input[type="text"] {
  width: 100%;
  padding: 8px 10px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: #0e0e0e;
  color: var(--fg);
  font-size: 13px;
}

.row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

button.primary {
  background: var(--accent);
  color: #04220f;
  border: none;
  font-weight: 700;
  padding: 9px 14px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 13px;
}
button.primary:hover { filter: brightness(1.08); }
button.primary:disabled { opacity: 0.5; cursor: default; }

button.secondary {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--fg);
  padding: 9px 14px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 13px;
}
button.secondary:hover { background: rgba(255,255,255,0.06); }

.copy-box {
  display: flex;
  gap: 6px;
  align-items: center;
}
.copy-box input {
  flex: 1;
  font-family: monospace;
  font-size: 11px;
}

.hint {
  font-size: 11px;
  color: var(--fg-dim);
}

.hidden { display: none !important; }

