:root {
  color-scheme: dark;
  --bg-rgb: 8 28 18;
  --bg-soft-rgb: 13 40 25;
  --fg: #f2fbf5;
  --fg-dim: #a9d9bb;
  --accent: #1db954;
  --border: rgb(29 185 84 / 0.25);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: transparent;
  color: var(--fg);
  font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}

.panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  background: rgb(var(--bg-rgb));
  border-radius: 10px;
  overflow: hidden;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  background: rgb(var(--bg-soft-rgb));
}

.cover {
  width: 36px;
  height: 36px;
  border-radius: 4px;
  object-fit: cover;
  background: #333;
  flex-shrink: 0;
}

.track-meta {
  min-width: 0;
  flex: 1;
}

.track-name {
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.track-artist {
  font-size: 11px;
  color: var(--fg-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.icon-btn {
  background: none;
  border: none;
  color: var(--fg-dim);
  cursor: pointer;
  padding: 6px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.icon-btn:hover { background: rgb(29 185 84 / 0.18); color: var(--fg); }
.icon-btn:disabled { opacity: 0.35; cursor: default; }
.icon-btn:disabled:hover { background: none; }

.controls-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgb(var(--bg-soft-rgb));
  border-bottom: 1px solid var(--border);
}

.play-btn { font-size: 17px; color: var(--fg); }

.time-label {
  font-size: 10px;
  color: var(--fg-dim);
  min-width: 28px;
  text-align: center;
  flex-shrink: 0;
}

.seek-bar {
  flex: 1;
  accent-color: var(--accent);
  height: 4px;
  cursor: pointer;
}

.lyrics-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 16px 20px;
  scroll-behavior: smooth;
}

.lyrics-line {
  font-size: 15px;
  line-height: 1.6;
  color: var(--fg-dim);
  padding: 3px 0;
  transition: color 0.2s ease, transform 0.2s ease;
  transform-origin: left center;
}

.lyrics-line.active {
  color: var(--fg);
  font-weight: 700;
  transform: scale(1.03);
}

.status-msg {
  color: var(--fg-dim);
  font-size: 13px;
  padding: 20px;
  text-align: center;
}

.attribution {
  padding: 6px 14px;
  font-size: 10px;
  color: var(--fg-dim);
  border-top: 1px solid var(--border);
  background: rgb(var(--bg-soft-rgb));
  display: flex;
  justify-content: space-between;
}
.attribution a { color: var(--accent); text-decoration: none; }

.setup {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: rgb(var(--bg-rgb));
  height: 100%;
  overflow-y: auto;
}

.setup label {
  font-size: 12px;
  color: var(--fg-dim);
}

.setup input[type="text"] {
  width: 100%;
  padding: 8px 10px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: rgb(6 18 11);
  color: var(--fg);
  font-size: 13px;
}

.row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

button.primary {
  background: var(--accent);
  color: #04220f;
  border: none;
  font-weight: 700;
  padding: 9px 14px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 13px;
}
button.primary:hover { filter: brightness(1.08); }
button.primary:disabled { opacity: 0.5; cursor: default; }

button.secondary {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--fg);
  padding: 9px 14px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 13px;
}
button.secondary:hover { background: rgb(29 185 84 / 0.12); }

.copy-box {
  display: flex;
  gap: 6px;
  align-items: center;
}
.copy-box input {
  flex: 1;
  font-family: monospace;
  font-size: 11px;
}

.hint {
  font-size: 11px;
  color: var(--fg-dim);
}

.hidden { display: none !important; }

